    re.compile(r'(?P<var>\w+)\s*=\s*skb_header_pointer\s*\('),
]

func_head = re.compile(r'^[A-Za-z_][\w\s\*,\(\)\[\]]*?\b(\w+)\s*\([^;]*$')

def function_spans(lines):
