            dm = re.match(r'^\s*(?:const\s+|static\s+)*(?:struct\s+|enum\s+|union\s+)?[A-Za-z_][A-Za-z0-9_]*\s*\*\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+?);\s*$', ln)
