                expr = am.group(2)
                if INTO_SKB.search(expr) or (CAST_PTR_RE.match(expr) and INTO_SKB.search(expr)):
                    captures.setdefault(am.group(1), (fs + idx + 1, expr.strip()))
        if not captures:
            continue
        for idx, ln in enumerate(body):
            if not PULL_RE.search(ln):
                continue
