pat_cap = re.compile(r'^\s*(?:const\s+)?(?:struct\s+\w+\s*|\w+\s*\*\s*)\*?\s*(\w+)\s*=\s*(.+?);\s*$')

def function_spans(lines):
    spans=[]
    cur=None; depth=0
    fstart=re.compile(r'^\w.*\(.*\)\s*$|^\w.*\(.*$')
    for i,l in enumerate(lines):
        if cur is None:
            if re.match(r'^(static\s+|inline\s+|__\w+\s+)*\w[\w\s\*]*\(', l) and not l.strip().startswith(('#','//','*')) and not re.search(r'\b(if|for|while|switch|else|return|sizeof)\s*\(', l):
                # find opening brace
                j=i; sig=''
                while j<len(lines) and j<i+8:
                    sig+=lines[j]
                    if '{' in lines[j]:
                        cur=(i,j); depth=0; break
                    if ';' in lines[j]:
                        break
                    j+=1
                if cur is None: continue
                # count braces from j
                start=cur[1]
                # recompute depth from start line
                seg=lines[start]
                depth=seg.count('{')-seg.count('}')
                cur=(i,start,depth)
        else:
            depth += l.count('{')-l.count('}')
            if depth<=0:
                spans.append((cur[0],cur[1],i))
                cur=None
    if cur: spans.append((cur[0],cur[1],len(lines)-1))
    return spans

results=[]
for dirpath,dirs,files in os.walk(root):
    if '/snapshots' not in dirpath:
        pass
    for f in files:
        if not f.endswith('.c'): continue
        p=os.path.join(dirpath,f)
        try: lines=open(p,encoding='utf-8',errors='ignore').read().split('\n')
        except: continue
        spans=function_spans(lines)
        for (fs,body_start,fe) in spans:
            body='\n'.join(lines[body_start:fe+1])
