                                if re.search(re.escape(cname)+r'\s*(->|\.)', lines[k]):
                                    used=True; ul=k+1; break
                        if used:
                            results.append((p,cl,cname,cinit,pl,ul))
                            break
for r in results:
    print('|'.join(str(x) for x in r))
print(len(results),'chains')
